import type { CSSProperties } from 'react';

import styled from '@emotion/styled';

import { theme } from '../../../theme';
import { IMAGE_ERROR_ILLUSTRATION_MAX_SIZE } from './Image.constants';
import type { ImageVariant } from './Image.types';

const objectFitByVariant: Record<
  ImageVariant,
  NonNullable<CSSProperties['objectFit']>
> = {
  fill: 'cover',
  fit: 'contain',
  stretch: 'fill',
};

interface StyledImageProps {
  $aspectRatio: number;
  $position?: string;
  $variant: ImageVariant;
}

interface StyledOverlayProps {
  $isDisabled: boolean;
}

export const StyledImageContainer = styled('div')({
  position: 'relative',
  width: 'fit-content',
});

export const StyledImageElement = styled('img')<StyledImageProps>(
  ({ $aspectRatio, $position, $variant }) => ({
    aspectRatio: $aspectRatio,
    objectFit: objectFitByVariant[$variant],
    objectPosition: $position,
    verticalAlign: 'top',
  }),
);

export const StyledImageOverlay = styled('div')<StyledOverlayProps>(
  ({ $isDisabled }) => ({
    background: $isDisabled
      ? theme.colors.interfaceForegroundLabelSecondary
      : theme.colors.interfaceSurfaceSecondary,
    bottom: 0,
    height: '100%',
    left: 0,
    opacity: $isDisabled ? 1 : 0,
    position: 'absolute',
    top: 0,
    transition: '0.5s ease',
    width: '100%',
    '&:hover': {
      opacity: 1,
    },
  }),
);

export const StyledErrorIllustration = styled('div')({
  padding: theme.spacing['4'],
  width: 'fit-content',
  '& > img': {
    maxHeight: IMAGE_ERROR_ILLUSTRATION_MAX_SIZE,
    maxWidth: IMAGE_ERROR_ILLUSTRATION_MAX_SIZE,
  },
});
